REQUIRED = ["id", "objective", "preconditions", "steps", "test_data", "expected"]

def missing_fields(case):
    missing = []
    for f in REQUIRED:
        v = case.get(f)
        if v is None or (isinstance(v, str) and not v.strip()) or (isinstance(v, list) and len(v) == 0):
            missing.append(f)
    return sorted(missing)
